-- =========================================================================
-- NEXUS SMART CAMPUS PLATFORM — MASTER CONSOLIDATED DATABASE SCHEMA
-- DATABASE NAME: nexus_campus_db (Production Ready, Single Source of Truth)
-- =========================================================================

CREATE DATABASE IF NOT EXISTS nexus_campus_db;
USE nexus_campus_db;

-- 1. STUDENT MODULE TABLES
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, admission_number VARCHAR(100), roll_number VARCHAR(50) NOT NULL UNIQUE, college_name VARCHAR(255) DEFAULT 'NEXUS Institute of Technology', class VARCHAR(100) NOT NULL, degree_class VARCHAR(100) DEFAULT 'B.TECH', joining_year VARCHAR(10) DEFAULT '2023', ending_year VARCHAR(10) DEFAULT '2027', study_year VARCHAR(20) DEFAULT '2ND', semester VARCHAR(50) NOT NULL, department VARCHAR(150) NOT NULL, section VARCHAR(20) DEFAULT 'A', dob VARCHAR(50), blood_group VARCHAR(10), gender ENUM('Male', 'Female', 'Other'), photograph_url LONGTEXT, email VARCHAR(150) NOT NULL UNIQUE, mobile VARCHAR(20) NOT NULL, address TEXT NOT NULL, govt_id_type VARCHAR(100), govt_id_number VARCHAR(100), govt_id_photo_url LONGTEXT, college_doc_url LONGTEXT, father_name VARCHAR(150), father_phone VARCHAR(20), father_email VARCHAR(150), father_photo_url LONGTEXT, father_govt_id_type VARCHAR(100), father_govt_id_number VARCHAR(100), father_govt_id_photo_url LONGTEXT, mother_name VARCHAR(150), mother_phone VARCHAR(20), mother_email VARCHAR(150), mother_photo_url LONGTEXT, mother_govt_id_type VARCHAR(100), mother_govt_id_number VARCHAR(100), mother_govt_id_photo_url LONGTEXT, parent_contact VARCHAR(20), parent_occupation VARCHAR(100), admission_date VARCHAR(50), hobbies TEXT, interests TEXT, skills TEXT, conveyance_mode VARCHAR(50) DEFAULT 'Self', bus_route VARCHAR(150), bus_charges DECIMAL(10,2) DEFAULT 0.00, bus_payment_status VARCHAR(50), vehicle_type VARCHAR(20), parking_payment_term VARCHAR(50), parking_fee DECIMAL(10,2) DEFAULT 0.00, parking_payment_status VARCHAR(50), residence_type VARCHAR(50) DEFAULT 'Day Scholar', hostel_name VARCHAR(100), room_number VARCHAR(50), hostel_payment_term VARCHAR(50), hostel_fee DECIMAL(10,2) DEFAULT 0.00, hostel_payment_status VARCHAR(50) DEFAULT 'Unpaid', hostel_doc_url LONGTEXT, hostel_card_url LONGTEXT, is_active TINYINT(1) DEFAULT 1, password VARCHAR(255) NOT NULL, q1 TEXT, a1 VARCHAR(255), q2 TEXT, a2 VARCHAR(255), q3 TEXT, a3 VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_documents (id INT AUTO_INCREMENT PRIMARY KEY, student_roll_number VARCHAR(50) NOT NULL, document_title VARCHAR(255) NOT NULL, original_filename VARCHAR(255) NOT NULL, file_type VARCHAR(50) DEFAULT 'pdf', file_size VARCHAR(50) DEFAULT NULL, file_data_url LONGTEXT NOT NULL, uploaded_at VARCHAR(50) NOT NULL, verification_status ENUM('Verified', 'Pending Verification', 'Rejected') DEFAULT 'Verified', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_doc_roll (student_roll_number));
CREATE TABLE IF NOT EXISTS student_notes (id INT AUTO_INCREMENT PRIMARY KEY, note_id VARCHAR(100) NOT NULL UNIQUE, student_email VARCHAR(150) NOT NULL, title VARCHAR(255) NOT NULL, category VARCHAR(100) DEFAULT 'General', tags LONGTEXT, content LONGTEXT, is_pinned TINYINT(1) DEFAULT 0, is_archived TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_leaves (id INT AUTO_INCREMENT PRIMARY KEY, leave_id VARCHAR(100) NOT NULL UNIQUE, student_email VARCHAR(150) NOT NULL, student_name VARCHAR(150) NOT NULL, roll_number VARCHAR(50) NOT NULL, class_name VARCHAR(100) NOT NULL, leave_type ENUM('Medical', 'On Duty (OD)', 'Casual') NOT NULL DEFAULT 'Medical', start_date VARCHAR(50) NOT NULL, end_date VARCHAR(50) NOT NULL, reason TEXT NOT NULL, certificate_url LONGTEXT, status ENUM('Pending', 'Approved', 'Rejected') DEFAULT 'Pending', approver_email VARCHAR(150), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_safety_reports (id INT AUTO_INCREMENT PRIMARY KEY, report_id VARCHAR(100) NOT NULL UNIQUE, student_name VARCHAR(150) NOT NULL, student_email VARCHAR(150) NOT NULL, student_roll VARCHAR(50), title VARCHAR(255) NOT NULL, concern_date VARCHAR(50) NOT NULL, concern_time VARCHAR(50) NOT NULL, location VARCHAR(255) NOT NULL, category VARCHAR(100) NOT NULL, severity VARCHAR(50) NOT NULL DEFAULT 'Medium', person_reported VARCHAR(255), student_description TEXT NOT NULL, detailed_concern LONGTEXT NOT NULL, is_anonymous TINYINT(1) DEFAULT 0, reported_to LONGTEXT, attachments LONGTEXT, status ENUM('Draft', 'Submitted', 'Under Review', 'Assigned', 'In Progress', 'Resolved', 'Closed') DEFAULT 'Submitted', timeline LONGTEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS safety_feedback_suggestions (id INT AUTO_INCREMENT PRIMARY KEY, feedback_id VARCHAR(100) NOT NULL UNIQUE, student_name VARCHAR(150) NOT NULL, student_email VARCHAR(150) NOT NULL, feedback_type VARCHAR(100) NOT NULL, subject VARCHAR(255) NOT NULL, description LONGTEXT NOT NULL, rating INT DEFAULT 5, is_anonymous TINYINT(1) DEFAULT 0, attachments LONGTEXT, status VARCHAR(50) DEFAULT 'Received', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS emergency_sos_alerts (id INT AUTO_INCREMENT PRIMARY KEY, alert_id VARCHAR(100) NOT NULL UNIQUE, student_name VARCHAR(150) NOT NULL, student_email VARCHAR(150) NOT NULL, student_mobile VARCHAR(50), emergency_type VARCHAR(100) NOT NULL, short_description TEXT, location_text VARCHAR(255) NOT NULL, latitude VARCHAR(50), longitude VARCHAR(50), status ENUM('Sending', 'Alert Sent', 'Help Response Received', 'Resolved') DEFAULT 'Alert Sent', responded_by VARCHAR(255) DEFAULT 'Campus Security & Welfare Cell', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_self_tests (id INT AUTO_INCREMENT PRIMARY KEY, test_id VARCHAR(100) NOT NULL UNIQUE, student_email VARCHAR(150) NOT NULL, title VARCHAR(255) NOT NULL, source_material_name VARCHAR(255), test_type ENUM('Objective', 'Subjective') NOT NULL, questions_count INT NOT NULL, duration_minutes INT NOT NULL, difficulty VARCHAR(50) DEFAULT 'Medium', questions_json LONGTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_test_attempts (id INT AUTO_INCREMENT PRIMARY KEY, attempt_id VARCHAR(100) NOT NULL UNIQUE, test_id VARCHAR(100) NOT NULL, student_email VARCHAR(150) NOT NULL, start_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, end_time TIMESTAMP NULL, submitted_at TIMESTAMP NULL, answers_json LONGTEXT, score DECIMAL(5,2) DEFAULT 0.00, max_score DECIMAL(5,2) DEFAULT 100.00, accuracy_percent DECIMAL(5,2) DEFAULT 0.00, violations_json LONGTEXT, status ENUM('In Progress', 'Completed', 'Auto Submitted') DEFAULT 'In Progress', ai_report_json LONGTEXT);

-- 2. FACULTY MODULE TABLES
CREATE TABLE IF NOT EXISTS faculties (id INT AUTO_INCREMENT PRIMARY KEY, faculty_name VARCHAR(150) NOT NULL, employee_id VARCHAR(50) NOT NULL UNIQUE, department VARCHAR(150) NOT NULL, designation VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, mobile VARCHAR(20) NOT NULL, dob VARCHAR(50), blood_group VARCHAR(10), address TEXT NOT NULL, joining_date VARCHAR(50), subjects_taught TEXT, photograph_url LONGTEXT, is_class_incharge VARCHAR(10) DEFAULT 'No', incharge_class VARCHAR(100) DEFAULT NULL, password VARCHAR(255) NOT NULL, q1 TEXT, a1 VARCHAR(255), q2 TEXT, a2 VARCHAR(255), q3 TEXT, a3 VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS faculty_notes (id INT AUTO_INCREMENT PRIMARY KEY, faculty_email VARCHAR(150) NOT NULL, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, category VARCHAR(50) DEFAULT 'Personal', is_pinned TINYINT(1) DEFAULT 0, is_archived TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS faculty_tasks (id INT AUTO_INCREMENT PRIMARY KEY, faculty_email VARCHAR(150) NOT NULL, title VARCHAR(255) NOT NULL, description TEXT DEFAULT NULL, due_date VARCHAR(50) DEFAULT NULL, priority VARCHAR(20) DEFAULT 'NORMAL', category VARCHAR(50) DEFAULT 'Teaching', status VARCHAR(20) DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

-- 3. PARENT MODULE TABLES
CREATE TABLE IF NOT EXISTS parents (id INT AUTO_INCREMENT PRIMARY KEY, parent_name VARCHAR(150) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, mobile VARCHAR(20) NOT NULL, occupation VARCHAR(100), address TEXT NOT NULL, student_name VARCHAR(150) NOT NULL, student_roll_number VARCHAR(50) NOT NULL, relationship ENUM('Father', 'Mother', 'Guardian') NOT NULL, password VARCHAR(255) NOT NULL, q1 TEXT, a1 VARCHAR(255), q2 TEXT, a2 VARCHAR(255), q3 TEXT, a3 VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

-- 4. ALUMNI MODULE TABLES
CREATE TABLE IF NOT EXISTS alumni (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, username VARCHAR(100), email VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, mobile VARCHAR(20), photograph_url LONGTEXT, cover_photo_url LONGTEXT, graduation_year VARCHAR(10) NOT NULL, batch VARCHAR(50), degree VARCHAR(100) DEFAULT 'B.Tech', department VARCHAR(150) NOT NULL, section VARCHAR(20), student_registration_number VARCHAR(100), college_name VARCHAR(255) DEFAULT 'NEXUS Institute of Technology', current_city VARCHAR(100), current_country VARCHAR(100), current_company VARCHAR(150), current_designation VARCHAR(150), industry VARCHAR(150), skills TEXT, bio TEXT, linkedin_url VARCHAR(255), github_url VARCHAR(255), other_links TEXT, alumni_id VARCHAR(50) UNIQUE, verification_status ENUM('PENDING', 'VERIFIED', 'REJECTED', 'SUSPENDED') DEFAULT 'PENDING', privacy_level ENUM('PUBLIC', 'CAMPUS_ONLY', 'CONNECTIONS_ONLY', 'PRIVATE') DEFAULT 'CAMPUS_ONLY', mentorship_available TINYINT(1) DEFAULT 1, job_provider TINYINT(1) DEFAULT 0, q1 TEXT, a1 VARCHAR(255), q2 TEXT, a2 VARCHAR(255), q3 TEXT, a3 VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alumni_experiences (id INT AUTO_INCREMENT PRIMARY KEY, alumni_email VARCHAR(150) NOT NULL, company VARCHAR(150) NOT NULL, designation VARCHAR(150) NOT NULL, start_date VARCHAR(50), end_date VARCHAR(50), is_current TINYINT(1) DEFAULT 0, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alumni_achievements (id INT AUTO_INCREMENT PRIMARY KEY, alumni_email VARCHAR(150) NOT NULL, title VARCHAR(255) NOT NULL, category VARCHAR(100), organization VARCHAR(255), achievement_date VARCHAR(50), description TEXT, media_url LONGTEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alumni_mentorship_requests (id INT AUTO_INCREMENT PRIMARY KEY, request_id VARCHAR(100) NOT NULL UNIQUE, student_email VARCHAR(150) NOT NULL, student_name VARCHAR(150) NOT NULL, student_roll_number VARCHAR(50), student_department VARCHAR(150), alumni_email VARCHAR(150) NOT NULL, alumni_name VARCHAR(150) NOT NULL, career_goal VARCHAR(255), preferred_topic VARCHAR(150), message TEXT NOT NULL, resume_url LONGTEXT, status ENUM('PENDING', 'ACCEPTED', 'REJECTED', 'COMPLETED') DEFAULT 'PENDING', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alumni_job_posts (id INT AUTO_INCREMENT PRIMARY KEY, job_id VARCHAR(100) NOT NULL UNIQUE, posted_by_email VARCHAR(150) NOT NULL, posted_by_name VARCHAR(150) NOT NULL, alumni_id VARCHAR(50), job_title VARCHAR(255) NOT NULL, company VARCHAR(255) NOT NULL, location VARCHAR(150) NOT NULL, work_mode VARCHAR(50) DEFAULT 'On-site', employment_type VARCHAR(50) DEFAULT 'Full-Time', experience_level VARCHAR(100), required_skills TEXT, description TEXT NOT NULL, application_link VARCHAR(255), deadline VARCHAR(50), poster_url LONGTEXT, moderation_status ENUM('PENDING', 'APPROVED', 'REJECTED', 'EXPIRED') DEFAULT 'APPROVED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alumni_events (id INT AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(100) NOT NULL UNIQUE, organizer_email VARCHAR(150) NOT NULL, organizer_name VARCHAR(150) NOT NULL, event_name VARCHAR(255) NOT NULL, event_date VARCHAR(50) NOT NULL, event_time VARCHAR(50), venue VARCHAR(255) NOT NULL, event_mode VARCHAR(50) DEFAULT 'Offline', target_batch VARCHAR(100) DEFAULT 'All Batches', target_department VARCHAR(150) DEFAULT 'All Departments', description TEXT NOT NULL, registration_link VARCHAR(255), poster_url LONGTEXT, status ENUM('UPCOMING', 'COMPLETED', 'CANCELLED') DEFAULT 'UPCOMING', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alumni_collaborations (id INT AUTO_INCREMENT PRIMARY KEY, collab_id VARCHAR(100) NOT NULL UNIQUE, inviter_email VARCHAR(150) NOT NULL, inviter_name VARCHAR(150) NOT NULL, inviter_role VARCHAR(50) NOT NULL, invitee_email VARCHAR(150) NOT NULL, invitee_name VARCHAR(150) NOT NULL, invitee_role VARCHAR(50) NOT NULL, project_title VARCHAR(255) NOT NULL, description TEXT NOT NULL, required_skills TEXT, expected_duration VARCHAR(100), status ENUM('PENDING', 'ACCEPTED', 'REJECTED') DEFAULT 'PENDING', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

-- 5. ADMIN COMMAND CENTER MODULE TABLES
CREATE TABLE IF NOT EXISTS administrators (id INT AUTO_INCREMENT PRIMARY KEY, admin_name VARCHAR(150) NOT NULL UNIQUE, email VARCHAR(150) NOT NULL UNIQUE, mobile VARCHAR(20), department VARCHAR(150) NOT NULL DEFAULT 'Central Administration', access_level ENUM('Super Admin', 'Academic Admin', 'Safety Authority', 'Finance Admin', 'Standard Admin') DEFAULT 'Super Admin', address TEXT, password VARCHAR(255) NOT NULL, q1 TEXT, a1 VARCHAR(255), q2 TEXT, a2 VARCHAR(255), q3 TEXT, a3 VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, log_id VARCHAR(100) NOT NULL UNIQUE, admin_email VARCHAR(150) NOT NULL, admin_name VARCHAR(150) NOT NULL, action VARCHAR(100) NOT NULL, target_type VARCHAR(50) NOT NULL, target_id VARCHAR(150) DEFAULT NULL, details TEXT, previous_value TEXT DEFAULT NULL, new_value TEXT DEFAULT NULL, ip_address VARCHAR(50) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, dept_code VARCHAR(50) NOT NULL UNIQUE, dept_name VARCHAR(150) NOT NULL, hod_name VARCHAR(150) DEFAULT NULL, hod_email VARCHAR(150) DEFAULT NULL, description TEXT, status VARCHAR(20) DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes (id INT AUTO_INCREMENT PRIMARY KEY, class_code VARCHAR(50) NOT NULL UNIQUE, class_name VARCHAR(150) NOT NULL, department VARCHAR(150) NOT NULL, semester VARCHAR(50) NOT NULL, section VARCHAR(20) NOT NULL, class_incharge_id INT DEFAULT NULL, class_incharge_email VARCHAR(150) DEFAULT NULL, class_incharge_name VARCHAR(150) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS class_broadcasts (id INT AUTO_INCREMENT PRIMARY KEY, broadcast_id VARCHAR(100) NOT NULL, faculty_email VARCHAR(150) NOT NULL, faculty_name VARCHAR(150) NOT NULL, class_code VARCHAR(50) NOT NULL, title VARCHAR(255) NOT NULL, message TEXT NOT NULL, category VARCHAR(50) DEFAULT 'GENERAL', priority VARCHAR(50) DEFAULT 'NORMAL', recipient_count INT DEFAULT 0, target_type VARCHAR(50) DEFAULT 'ENTIRE_CLASS', selected_students TEXT DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campus_announcements (id INT AUTO_INCREMENT PRIMARY KEY, announcement_id VARCHAR(100) NOT NULL UNIQUE, publisher_name VARCHAR(150) NOT NULL, publisher_email VARCHAR(150) NOT NULL, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, category VARCHAR(50) DEFAULT 'GENERAL', target_audience VARCHAR(100) DEFAULT 'ALL', target_department VARCHAR(150) DEFAULT 'ALL', target_class VARCHAR(100) DEFAULT 'ALL', priority VARCHAR(20) DEFAULT 'NORMAL', is_pinned TINYINT(1) DEFAULT 0, is_archived TINYINT(1) DEFAULT 0, status VARCHAR(20) DEFAULT 'PUBLISHED', attachment_url LONGTEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT, updated_by VARCHAR(150), updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_lockouts (id INT AUTO_INCREMENT PRIMARY KEY, identifier VARCHAR(150) NOT NULL, user_role ENUM('Student', 'Faculty', 'Parent', 'Alumni', 'Administrator') NOT NULL, failed_attempts INT DEFAULT 0, locked_until TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

-- 6. ACADEMICS & GENERAL CAMPUS UTILITIES TABLES
CREATE TABLE IF NOT EXISTS timetables (id VARCHAR(100) PRIMARY KEY, timetable_id VARCHAR(100) DEFAULT 'ACTIVE_TT_V1', day ENUM('Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday') NOT NULL, start_time VARCHAR(20) NOT NULL, end_time VARCHAR(20) NOT NULL, slot_name VARCHAR(100) NOT NULL, subject VARCHAR(150) NOT NULL, code VARCHAR(50) NOT NULL, teacher_code VARCHAR(50) NOT NULL, canonical_faculty_key VARCHAR(100), class_name VARCHAR(100) NOT NULL, canonical_class_key VARCHAR(100), room VARCHAR(50) NOT NULL, canonical_venue_key VARCHAR(100), type ENUM('Lecture', 'Lab', 'Project', 'Seminar', 'Break') DEFAULT 'Lecture', slot_type VARCHAR(50) DEFAULT 'LECTURE', break_type VARCHAR(50) DEFAULT NULL, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_class (class_name), INDEX idx_day_slot (day, start_time), INDEX idx_room (room));
CREATE TABLE IF NOT EXISTS timetable_metadata (id INT AUTO_INCREMENT PRIMARY KEY, timetable_id VARCHAR(100) DEFAULT 'ACTIVE_TT_V1', file_name VARCHAR(255) NOT NULL, uploaded_at VARCHAR(100) NOT NULL, uploader_name VARCHAR(150) DEFAULT 'System Administrator', uploader_role VARCHAR(50) DEFAULT 'Administrator', total_lectures INT DEFAULT 0, selected_class VARCHAR(100) DEFAULT 'BTECH CSE 4A', version INT DEFAULT 1, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT DEFAULT NULL, roll_number VARCHAR(50) NOT NULL, student_name VARCHAR(150) NOT NULL, class_name VARCHAR(100) NOT NULL, department VARCHAR(150) NOT NULL, semester VARCHAR(50) NOT NULL, section VARCHAR(20) DEFAULT NULL, subject VARCHAR(150) NOT NULL, subject_code VARCHAR(50) NOT NULL, date DATE NOT NULL, time_slot VARCHAR(50) DEFAULT NULL, status ENUM('Present', 'Absent', 'Medical Leave', 'On Duty (OD)', 'Suspended', 'Fees Not Paid but present (FP)', 'Fees Not Paid and Absent (FA)') NOT NULL DEFAULT 'Present', faculty_name VARCHAR(150) DEFAULT NULL, remarks TEXT DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_roll_class (roll_number, class_name), INDEX idx_class_date (class_name, date), INDEX idx_student (student_id));
CREATE TABLE IF NOT EXISTS assignments (id INT AUTO_INCREMENT PRIMARY KEY, assignment_id VARCHAR(100) DEFAULT NULL, topic_name VARCHAR(255) NOT NULL, subject_name VARCHAR(150) NOT NULL, subject_code VARCHAR(50) NOT NULL, faculty_name VARCHAR(150) NOT NULL, assignment_type ENUM('Objective', 'Subjective', 'Lab Project') DEFAULT 'Subjective', total_marks INT NOT NULL DEFAULT 50, scored_marks INT DEFAULT NULL, deadline_date DATE NOT NULL, deadline_time VARCHAR(20) DEFAULT '11:59 PM', status ENUM('Pending', 'Submitted', 'Evaluated', 'Late') DEFAULT 'Pending', submitted_date VARCHAR(50) DEFAULT NULL, uploaded_file_name VARCHAR(255) DEFAULT NULL, uploaded_file_type VARCHAR(50) DEFAULT NULL, uploaded_file_size VARCHAR(50) DEFAULT NULL, faculty_remarks TEXT DEFAULT NULL, description TEXT DEFAULT NULL, student_roll_number VARCHAR(50) DEFAULT '2026CSE001', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_assignment_roll (student_roll_number), INDEX idx_assignment_code (subject_code));
CREATE TABLE IF NOT EXISTS assignment_submissions (id INT AUTO_INCREMENT PRIMARY KEY, submission_id VARCHAR(100) NOT NULL UNIQUE, assignment_id VARCHAR(100) NOT NULL, student_email VARCHAR(150) NOT NULL, roll_number VARCHAR(50) NOT NULL, student_name VARCHAR(150) NOT NULL, class_name VARCHAR(100) NOT NULL, submitted_date VARCHAR(100) NOT NULL, uploaded_file_name VARCHAR(255), uploaded_file_type VARCHAR(50), uploaded_file_size VARCHAR(50), uploaded_file_url LONGTEXT, status ENUM('Pending', 'Submitted', 'Incomplete but Submitted', 'Graded') DEFAULT 'Submitted', scored_marks INT DEFAULT NULL, faculty_remarks TEXT DEFAULT NULL, graded_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS digital_cards (id INT AUTO_INCREMENT PRIMARY KEY, student_roll_number VARCHAR(50) NOT NULL, card_type ENUM('Library Card', 'Fest Card') NOT NULL, card_number VARCHAR(100) NOT NULL UNIQUE, event_name VARCHAR(150) DEFAULT NULL, event_dates VARCHAR(150) DEFAULT NULL, duration VARCHAR(100) DEFAULT NULL, approved_by VARCHAR(150) DEFAULT 'Class Incharge / HOD', status ENUM('Active', 'Expired', 'Pending Approval') DEFAULT 'Active', issue_date DATE NOT NULL, valid_until DATE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_card_roll (student_roll_number));
CREATE TABLE IF NOT EXISTS fee_payments (id INT AUTO_INCREMENT PRIMARY KEY, student_roll_number VARCHAR(50) NOT NULL, fee_type VARCHAR(150) NOT NULL, semester VARCHAR(50) NOT NULL, amount DECIMAL(10,2) NOT NULL, due_date DATE NOT NULL, payment_status ENUM('Paid', 'Pending', 'Overdue') DEFAULT 'Pending', razorpay_order_id VARCHAR(100) DEFAULT NULL, razorpay_payment_id VARCHAR(100) DEFAULT NULL, paid_on DATETIME DEFAULT NULL, receipt_no VARCHAR(100) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_fee_roll (student_roll_number));
CREATE TABLE IF NOT EXISTS events_and_elections (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, category ENUM('College Fest', 'Tech Hackathon', 'Student Election', 'Workshop', 'Sports Meet') NOT NULL, event_date DATE NOT NULL, start_time VARCHAR(20) DEFAULT '09:00 AM', venue VARCHAR(150) NOT NULL, organizer VARCHAR(150) DEFAULT 'Student Council', description TEXT, approval_status ENUM('Approved', 'Pending', 'Rejected') DEFAULT 'Approved', approved_by VARCHAR(150) DEFAULT 'Dean Student Affairs', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quick_notes (id INT AUTO_INCREMENT PRIMARY KEY, user_identifier VARCHAR(150) NOT NULL, note_title VARCHAR(255) NOT NULL, note_body TEXT, color_tag VARCHAR(50) DEFAULT 'purple', is_pinned TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS announcements (id INT AUTO_INCREMENT PRIMARY KEY, announcement_id VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, message LONGTEXT NOT NULL, category VARCHAR(100) DEFAULT 'Academic', target_audience ENUM('All Students', 'Class', 'Department') DEFAULT 'Class', target_class VARCHAR(100) DEFAULT 'BTECH CSE 4A', faculty_name VARCHAR(150) NOT NULL, faculty_email VARCHAR(150) NOT NULL, attachment_url LONGTEXT, priority ENUM('Normal', 'High', 'Urgent') DEFAULT 'Normal', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

-- 7. CANTEEN MODULE TABLES
CREATE TABLE IF NOT EXISTS canteen_outlets (id INT AUTO_INCREMENT PRIMARY KEY, outlet_name VARCHAR(150) NOT NULL UNIQUE, location VARCHAR(255) NOT NULL, operating_hours VARCHAR(100) NOT NULL, rating DECIMAL(2,1) DEFAULT 4.8, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS canteen_items (id INT AUTO_INCREMENT PRIMARY KEY, outlet_id INT NOT NULL, name VARCHAR(150) NOT NULL, category ENUM('Combos & Meal Deals', 'Fast Food & Snacks', 'Hot & Cold Beverages', 'Healthy Salads & Bowls', 'South & North Indian', 'Desserts & Sweets') NOT NULL, price DECIMAL(10,2) NOT NULL, original_price DECIMAL(10,2) DEFAULT NULL, rating DECIMAL(2,1) DEFAULT 4.8, prep_time VARCHAR(50) DEFAULT '10 mins', calories VARCHAR(50) DEFAULT '300 kcal', is_veg TINYINT(1) DEFAULT 1, is_bestseller TINYINT(1) DEFAULT 0, image_url TEXT, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (outlet_id) REFERENCES canteen_outlets(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS canteen_promos (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, title VARCHAR(150) NOT NULL, description TEXT, discount_percent INT NOT NULL, min_order_amount DECIMAL(10,2) NOT NULL DEFAULT 100.00, badge VARCHAR(50) DEFAULT 'SPECIAL OFFER', is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS canteen_orders (id INT AUTO_INCREMENT PRIMARY KEY, token_no VARCHAR(50) NOT NULL UNIQUE, student_roll_number VARCHAR(50) NOT NULL, subtotal DECIMAL(10,2) NOT NULL, discount_amount DECIMAL(10,2) DEFAULT 0.00, grand_total DECIMAL(10,2) NOT NULL, pickup_counter VARCHAR(150) DEFAULT 'Express Pick-Up Counter #1 (North Wing)', payment_method VARCHAR(100) NOT NULL, payment_status ENUM('PAID', 'PENDING', 'FAILED') DEFAULT 'PAID', order_status ENUM('Kitchen Preparing', 'Ready for Pick-Up', 'Completed', 'Cancelled') DEFAULT 'Kitchen Preparing', estimated_time VARCHAR(50) DEFAULT '10-12 mins', order_date DATE NOT NULL, order_time VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_order_roll (student_roll_number), INDEX idx_token (token_no));
CREATE TABLE IF NOT EXISTS canteen_order_items (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, item_name VARCHAR(150) NOT NULL, quantity INT NOT NULL DEFAULT 1, price DECIMAL(10,2) NOT NULL, total_price DECIMAL(10,2) NOT NULL, FOREIGN KEY (order_id) REFERENCES canteen_orders(id) ON DELETE CASCADE);

-- 8. CONNECTIONS & MESSAGING SOCIAL MODULE TABLES
CREATE TABLE IF NOT EXISTS connections_profiles (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(150) NOT NULL UNIQUE, username VARCHAR(100) NOT NULL UNIQUE, full_name VARCHAR(150) NOT NULL, college VARCHAR(255) NOT NULL DEFAULT 'PCTE College', university VARCHAR(255) DEFAULT 'Punjab Technical University', city VARCHAR(100) DEFAULT 'Ludhiana', department VARCHAR(150) NOT NULL DEFAULT 'Computer Science', course VARCHAR(100) NOT NULL DEFAULT 'B.Tech CSE', semester VARCHAR(50) NOT NULL DEFAULT '7th Semester', graduation_year VARCHAR(10) DEFAULT '2026', bio TEXT, skills LONGTEXT, interests LONGTEXT, achievements LONGTEXT, projects LONGTEXT, github VARCHAR(255), linkedin VARCHAR(255), portfolio VARCHAR(255), avatar_url LONGTEXT, cover_url LONGTEXT, is_open_collaboration TINYINT(1) DEFAULT 1, profile_visibility ENUM('Public', 'Connections', 'My College') DEFAULT 'Public', messaging_permission ENUM('Everyone', 'Connections', 'Nobody') DEFAULT 'Everyone', request_permission ENUM('Everyone', 'Same College', 'Nobody') DEFAULT 'Everyone', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connection_requests (id INT AUTO_INCREMENT PRIMARY KEY, request_id VARCHAR(100) NOT NULL UNIQUE, sender_email VARCHAR(150) NOT NULL, receiver_email VARCHAR(150) NOT NULL, message TEXT, status ENUM('Pending', 'Accepted', 'Rejected', 'Cancelled') DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_friendships (id INT AUTO_INCREMENT PRIMARY KEY, friendship_id VARCHAR(100) NOT NULL UNIQUE, user1_email VARCHAR(150) NOT NULL, user2_email VARCHAR(150) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_blocked_users (id INT AUTO_INCREMENT PRIMARY KEY, block_id VARCHAR(100) NOT NULL UNIQUE, blocker_email VARCHAR(150) NOT NULL, blocked_email VARCHAR(150) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_posts (id INT AUTO_INCREMENT PRIMARY KEY, post_id VARCHAR(100) NOT NULL UNIQUE, author_email VARCHAR(150) NOT NULL, author_name VARCHAR(150) NOT NULL, author_username VARCHAR(100) NOT NULL, author_college VARCHAR(255) NOT NULL, author_avatar LONGTEXT, content LONGTEXT NOT NULL, media LONGTEXT, location VARCHAR(255), tags LONGTEXT, visibility ENUM('Public Network', 'Connections', 'My College', 'Only Me') DEFAULT 'Public Network', likes_count INT DEFAULT 0, dislikes_count INT DEFAULT 0, comments_count INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_post_reactions (id INT AUTO_INCREMENT PRIMARY KEY, post_id VARCHAR(100) NOT NULL, user_email VARCHAR(150) NOT NULL, reaction_type ENUM('Like', 'Dislike') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY user_post_reaction (post_id, user_email));
CREATE TABLE IF NOT EXISTS connections_post_comments (id INT AUTO_INCREMENT PRIMARY KEY, comment_id VARCHAR(100) NOT NULL UNIQUE, post_id VARCHAR(100) NOT NULL, author_email VARCHAR(150) NOT NULL, author_name VARCHAR(150) NOT NULL, author_username VARCHAR(100) NOT NULL, author_avatar LONGTEXT, comment_text TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_saved_posts (id INT AUTO_INCREMENT PRIMARY KEY, user_email VARCHAR(150) NOT NULL, post_id VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY user_saved_post (user_email, post_id));
CREATE TABLE IF NOT EXISTS connections_reels (id INT AUTO_INCREMENT PRIMARY KEY, reel_id VARCHAR(100) NOT NULL UNIQUE, creator_email VARCHAR(150) NOT NULL, creator_name VARCHAR(150) NOT NULL, creator_username VARCHAR(100) NOT NULL, creator_college VARCHAR(255) NOT NULL, creator_avatar LONGTEXT, video_url LONGTEXT NOT NULL, caption TEXT, likes_count INT DEFAULT 0, dislikes_count INT DEFAULT 0, comments_count INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_collaborations (id INT AUTO_INCREMENT PRIMARY KEY, collab_id VARCHAR(100) NOT NULL UNIQUE, creator_email VARCHAR(150) NOT NULL, creator_name VARCHAR(150) NOT NULL, creator_username VARCHAR(100) NOT NULL, title VARCHAR(255) NOT NULL, type VARCHAR(100) NOT NULL, description LONGTEXT NOT NULL, skills_required LONGTEXT, role_offered VARCHAR(150), expected_contribution TEXT, start_date VARCHAR(50), end_date VARCHAR(50), college VARCHAR(255) NOT NULL, department VARCHAR(150), status VARCHAR(50) DEFAULT 'Open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_conversations (id INT AUTO_INCREMENT PRIMARY KEY, conv_id VARCHAR(100) NOT NULL UNIQUE, participant1_email VARCHAR(150) NOT NULL, participant2_email VARCHAR(150) NOT NULL, last_message TEXT, last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_messages (id INT AUTO_INCREMENT PRIMARY KEY, message_id VARCHAR(100) NOT NULL UNIQUE, conv_id VARCHAR(100) NOT NULL, sender_email VARCHAR(150) NOT NULL, receiver_email VARCHAR(150) NOT NULL, content LONGTEXT, media_url LONGTEXT, media_type VARCHAR(50), voice_note_url LONGTEXT, reactions LONGTEXT, status ENUM('Sent', 'Delivered', 'Seen') DEFAULT 'Sent', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connections_user_reports (id INT AUTO_INCREMENT PRIMARY KEY, report_id VARCHAR(100) NOT NULL UNIQUE, reporter_email VARCHAR(150) NOT NULL, target_type ENUM('User', 'Post', 'Comment', 'Message') NOT NULL, target_id VARCHAR(100) NOT NULL, category VARCHAR(100) NOT NULL, description TEXT, status VARCHAR(50) DEFAULT 'Under Review', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assessment_schemes (id INT AUTO_INCREMENT PRIMARY KEY, scheme_id VARCHAR(100) NOT NULL UNIQUE, academic_session VARCHAR(50) NOT NULL DEFAULT '2025-2026', department VARCHAR(150) NOT NULL, class_name VARCHAR(100) NOT NULL, semester VARCHAR(50) NOT NULL, subject_name VARCHAR(150) NOT NULL, subject_code VARCHAR(50) NOT NULL, faculty_email VARCHAR(150) NOT NULL, components_json LONGTEXT NOT NULL, attendance_policy_json LONGTEXT DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_scheme_class (class_name), INDEX idx_scheme_subj (subject_code));
CREATE TABLE IF NOT EXISTS student_assessment_marks (id INT AUTO_INCREMENT PRIMARY KEY, mark_id VARCHAR(100) NOT NULL UNIQUE, scheme_id VARCHAR(100) NOT NULL, subject_code VARCHAR(50) NOT NULL, subject_name VARCHAR(150) NOT NULL, class_name VARCHAR(100) NOT NULL, semester VARCHAR(50) NOT NULL, student_roll VARCHAR(50) NOT NULL, student_name VARCHAR(150) NOT NULL, student_email VARCHAR(150) NOT NULL, component_name VARCHAR(100) NOT NULL, marks_obtained DECIMAL(5, 2) NOT NULL DEFAULT 0.00, max_marks DECIMAL(5, 2) NOT NULL DEFAULT 100.00, attendance_percent DECIMAL(5, 2) DEFAULT NULL, attendance_marks DECIMAL(5, 2) DEFAULT NULL, total_score DECIMAL(5, 2) DEFAULT NULL, grade VARCHAR(10) DEFAULT NULL, status ENUM('Draft', 'Saved', 'Published', 'Corrected') DEFAULT 'Draft', faculty_email VARCHAR(150) NOT NULL, faculty_remarks TEXT DEFAULT NULL, published_at TIMESTAMP NULL DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_sch_stu_comp (scheme_id, student_roll, component_name), INDEX idx_mark_student (student_roll), INDEX idx_mark_subj (subject_code));
CREATE TABLE IF NOT EXISTS marks_audit_log (id INT AUTO_INCREMENT PRIMARY KEY, log_id VARCHAR(100) NOT NULL UNIQUE, mark_id VARCHAR(100) NOT NULL, student_roll VARCHAR(50) NOT NULL, subject_code VARCHAR(50) NOT NULL, component_name VARCHAR(100) NOT NULL, previous_marks DECIMAL(5, 2) DEFAULT NULL, new_marks DECIMAL(5, 2) NOT NULL, reason TEXT NOT NULL, corrected_by VARCHAR(150) NOT NULL, corrected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS faculty_leaves (id INT AUTO_INCREMENT PRIMARY KEY, leave_id VARCHAR(100) NOT NULL UNIQUE, faculty_email VARCHAR(150) NOT NULL, faculty_name VARCHAR(150) NOT NULL, employee_id VARCHAR(50), department VARCHAR(150) NOT NULL, leave_type ENUM('Casual', 'Earned', 'Medical', 'On Duty (OD)', 'Maternity/Paternity', 'Compensatory') NOT NULL DEFAULT 'Casual', start_date VARCHAR(50) NOT NULL, end_date VARCHAR(50) NOT NULL, days_count INT NOT NULL DEFAULT 1, reason TEXT NOT NULL, attachment_url LONGTEXT, substitute_faculty VARCHAR(150), status ENUM('Pending', 'Approved', 'Rejected', 'Clarification Requested') DEFAULT 'Pending', approver_email VARCHAR(150), approver_name VARCHAR(150), approver_remarks TEXT, decision_date TIMESTAMP NULL DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_fac_leave_email (faculty_email));
CREATE TABLE IF NOT EXISTS faculty_research_projects (id INT AUTO_INCREMENT PRIMARY KEY, project_id VARCHAR(100) NOT NULL UNIQUE, creator_email VARCHAR(150) NOT NULL, creator_name VARCHAR(150) NOT NULL, department VARCHAR(150) NOT NULL, institution VARCHAR(255) DEFAULT 'NEXUS Institute of Technology', title VARCHAR(255) NOT NULL, research_domain VARCHAR(150) NOT NULL, description LONGTEXT NOT NULL, required_expertise TEXT, visibility ENUM('Intra-College', 'Inter-College', 'Public') DEFAULT 'Intra-College', project_stage ENUM('Proposal / Ideation', 'Active / Ongoing', 'Review / Submission', 'Published / Completed') DEFAULT 'Proposal / Ideation', milestones_json LONGTEXT, status ENUM('Draft', 'Published', 'Active', 'Completed', 'Archived') DEFAULT 'Published', members_json LONGTEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_res_proj_creator (creator_email));
CREATE TABLE IF NOT EXISTS faculty_research_requests (id INT AUTO_INCREMENT PRIMARY KEY, request_id VARCHAR(100) NOT NULL UNIQUE, project_id VARCHAR(100) NOT NULL, applicant_email VARCHAR(150) NOT NULL, applicant_name VARCHAR(150) NOT NULL, applicant_department VARCHAR(150) NOT NULL, applicant_institution VARCHAR(255) DEFAULT 'NEXUS Institute of Technology', message TEXT NOT NULL, proposed_role VARCHAR(150), status ENUM('Pending', 'Accepted', 'Rejected') DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_res_req_proj (project_id));
CREATE TABLE IF NOT EXISTS emergency_sos_responders (id INT AUTO_INCREMENT PRIMARY KEY, alert_id VARCHAR(100) NOT NULL, faculty_email VARCHAR(150) NOT NULL, faculty_name VARCHAR(150) NOT NULL, faculty_department VARCHAR(150), assigned_slot INT NOT NULL, response_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, action_notes TEXT, status ENUM('Responding', 'On Scene', 'Resolved') DEFAULT 'Responding', UNIQUE KEY uq_alert_fac (alert_id, faculty_email), INDEX idx_sos_alert (alert_id));

